import { CaretRight, Folder, FolderOpen, House } from "@phosphor-icons/react";
import type { Icon } from "@phosphor-icons/react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@workspace/ui/components/breadcrumb";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@workspace/ui/components/dropdown-menu";
import { useState } from "react";

type RootSegment = {
  label: string;
  href: string;
  icon: Icon;
};

const rootSegment: RootSegment = {
  label: "Home",
  href: "#",
  icon: House,
};

const currentLabel = "Release Notes";

const menuOptions = ["Updates", "Changelog", "Archive"] as const;

const Breadcrumb7 = () => {
  const [open, setOpen] = useState(false);
  const RootIcon = rootSegment.icon;

  return (
    <Breadcrumb>
      <BreadcrumbList className="gap-1.5 text-sm">
        <BreadcrumbItem>
          <BreadcrumbLink
            href={rootSegment.href}
            className="flex items-center gap-1.5 rounded-sm px-1 py-0.5 hover:text-foreground"
          >
            <RootIcon className="size-3.5 text-muted-foreground" />
            <span className="sr-only">{rootSegment.label}</span>
          </BreadcrumbLink>
        </BreadcrumbItem>
        <BreadcrumbSeparator className="text-muted-foreground/60">
          <CaretRight className="size-3.5" />
        </BreadcrumbSeparator>
        <BreadcrumbItem className="flex items-center">
          <DropdownMenu open={open} onOpenChange={setOpen}>
            <DropdownMenuTrigger className="inline-flex cursor-pointer items-center gap-1 rounded-sm px-1 py-0.5 text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none">
              {open ? <FolderOpen className="size-3.5" /> : <Folder className="size-3.5" />}
              <span className="sr-only">{open ? "Open section menu" : "Open section menu"}</span>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              {menuOptions.map((option) => (
                <DropdownMenuItem key={option}>{option}</DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </BreadcrumbItem>
        <BreadcrumbSeparator className="text-muted-foreground/60">
          <CaretRight className="size-3.5" />
        </BreadcrumbSeparator>
        <BreadcrumbItem>
          <BreadcrumbPage className="rounded-sm px-1 py-0.5 font-medium">
            {currentLabel}
          </BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </Breadcrumb>
  );
};

export default Breadcrumb7;
